/**
 * D201 §2 — THE AD'S PUBLIC ADDRESS.
 *
 * A visitor sees ONE key for an ad: its public id, ten characters of a
 * 31-symbol alphabet (no 0, 1, i, l or o — nothing to misread from a printed
 * QR), generated by the database at insert (M1). The uuid never appears in a
 * public address.
 *
 * The canonical address is `/l/<words>-<id>`: the words are the title's ASCII
 * fold — the app's slug derivation (lower case, every run of other characters
 * one `-`, no edge `-`), after NFKD so that accented letters keep their base,
 * cut at 60 characters on a word boundary. The words are for people and search
 * engines; the id decides. A title whose fold leaves nothing (Amharic, say)
 * gives the short form `/l/<id>`, which always resolves and is what the QR
 * carries. A segment whose words differ from the canonical ones is answered
 * with a 301 to the canonical by the route (the title can change; old links
 * keep working).
 *
 * This module is pure and client-safe: no import, no database, no browser API.
 * The server-only QR encoder (src/server/qr.ts) takes `isPublicId` from here.
 */

export const PUBLIC_ID_ALPHABET = "23456789abcdefghjkmnpqrstuvwxyz";
export const PUBLIC_ID_LENGTH = 10;
export const PUBLIC_ID_RE = /^[23456789abcdefghjkmnpqrstuvwxyz]{10}$/;

/** The longest words part of an address, in characters. */
export const ADDRESS_WORDS_MAX = 60;

export function isPublicId(value: string): boolean {
  return PUBLIC_ID_RE.test(value);
}

/**
 * The title's words for the address: NFKD with the combining marks dropped
 * (é → e), lower case, runs of anything but a–z and 0–9 become one `-`, no `-`
 * at either end, at most 60 characters cut at a `-` (never inside a word). ""
 * when nothing is left.
 */
export function addressWords(title: string): string {
  const folded = title
    .normalize("NFKD")
    .replace(/\p{M}+/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (folded.length <= ADDRESS_WORDS_MAX) return folded;
  let cut = folded.slice(0, ADDRESS_WORDS_MAX);
  if (folded.charAt(ADDRESS_WORDS_MAX) !== "-") {
    const boundary = cut.lastIndexOf("-");
    if (boundary > 0) cut = cut.slice(0, boundary);
  }
  return cut.replace(/-+$/g, "");
}

/** The canonical segment after `/l/`: `<words>-<id>`, or `<id>` alone. */
export function canonicalSegment(title: string, publicId: string): string {
  const words = addressWords(title);
  return words === "" ? publicId : `${words}-${publicId}`;
}

/** The canonical path `/l/<words>-<id>` (or `/l/<id>`). */
export function listingPath(title: string, publicId: string): string {
  return `/l/${canonicalSegment(title, publicId)}`;
}

/** The short path `/l/<id>` — what the QR carries. */
export function shortListingPath(publicId: string): string {
  return `/l/${publicId}`;
}

/** The canonical address on an origin (`https://ethio.com`, no trailing `/`). */
export function listingUrl(origin: string, title: string, publicId: string): string {
  return `${origin.replace(/\/+$/, "")}${listingPath(title, publicId)}`;
}

export interface ParsedAddress {
  /** The id the segment carries. */
  publicId: string;
  /** The words before it — "" for the short form. */
  words: string;
}

/**
 * Reads one segment after `/l/`: exactly an id → the short form; otherwise the
 * characters after the LAST `-` must be an id and what stands before it is the
 * words part. Anything else → null (the route's 404).
 */
export function parseAddressSegment(segment: string): ParsedAddress | null {
  if (isPublicId(segment)) return { publicId: segment, words: "" };
  const at = segment.lastIndexOf("-");
  if (at < 0) return null;
  const tail = segment.slice(at + 1);
  if (!isPublicId(tail)) return null;
  return { publicId: tail, words: segment.slice(0, at) };
}
